        #include "object_storage.h"

// 定义对象键名的最大长度
#define MAX_KEY_NAME_LENGTH 1024

// 对象元数据结构
typedef struct {
    char bucket_name[256];
    char object_key[MAX_KEY_NAME_LENGTH];
    int key_set;
} object_metadata_t;

// 全局对象元数据实例
static object_metadata_t g_object_metadata = {0};

int set_object_key_name(char* bucket_name, char* object_key) {
    // 检查输入参数是否为空
    if (bucket_name == NULL || object_key == NULL) {
        return -1; // 参数错误
    }

    // 检查桶名称长度
    size_t bucket_len = strlen(bucket_name);
    if (bucket_len == 0 || bucket_len >= sizeof(g_object_metadata.bucket_name)) {
        return -2; // 桶名称长度错误
    }

    // 检查对象键名长度
    size_t key_len = strlen(object_key);
    if (key_len == 0 || key_len >= sizeof(g_object_metadata.object_key)) {
        return -3; // 对象键名长度错误
    }

    // 复制桶名称到元数据结构
    strncpy(g_object_metadata.bucket_name, bucket_name, sizeof(g_object_metadata.bucket_name) - 1);
    g_object_metadata.bucket_name[sizeof(g_object_metadata.bucket_name) - 1] = '\0';

    // 复制对象键名到元数据结构
    strncpy(g_object_metadata.object_key, object_key, sizeof(g_object_metadata.object_key) - 1);
    g_object_metadata.object_key[sizeof(g_object_metadata.object_key) - 1] = '\0';

    // 标记键名已设置
    g_object_metadata.key_set = 1;

    return 0; // 成功设置键名
}
        ]]>
        </content>
    </code>
</result>
```


